// Rebuilds src/sandbox/runtime-bundle.js from the installed @abaplint/runtime.
//
// The bundle is committed rather than built by Vite because it is loaded as a
// plain <script> inside the execution Worker's blob: URL (see CLAUDE.md), so it
// has to be a self-contained IIFE that defines the `abaplintRuntime` global.
// Run this after bumping @abaplint/runtime — the transpiler emits calls the
// runtime must already implement, and a stale bundle turns a clean
// transpile_error into a runtime crash.
//
//   node scripts/build-runtime-bundle.mjs
//   node scripts/build-runtime-bundle.mjs --check   (fails if out of date)

import { build } from "esbuild";
import { readFile, writeFile } from "node:fs/promises";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";

const require = createRequire(import.meta.url);
// Everything is resolved from this file, not from the caller's cwd: run from a
// subdirectory with cwd-relative paths and the entry point vanishes while the
// output path points somewhere else entirely.
const REPO = fileURLToPath(new URL("..", import.meta.url));
const OUT = `${REPO}src/sandbox/runtime-bundle.js`;
const check = process.argv.includes("--check");

const version = require("@abaplint/runtime/package.json").version;
// esbuild is a caret range, so its output can change without any
// @abaplint/runtime bump. Reported on a mismatch so the message does not
// send the reader after the wrong package.
const esbuildVersion = require("esbuild/package.json").version;

const result = await build({
  // Kept relative and pinned to `absWorkingDir`: esbuild writes the entry's
  // path into the bundle as a comment, so an absolute path here would change
  // the output bytes on every machine and make `--check` unusable.
  absWorkingDir: REPO,
  entryPoints: ["node_modules/@abaplint/runtime/build/src/index.js"],
  bundle: true,
  format: "iife",
  globalName: "abaplintRuntime",
  platform: "browser",
  write: false,
});

const banner = `// Generated by scripts/build-runtime-bundle.mjs from @abaplint/runtime@${version}. Do not edit.\n`;
const next = banner + result.outputFiles[0].text;

if (check) {
  // Only a missing file becomes "out of date"; any other read error is a real
  // problem and must not be laundered into a stale-bundle report.
  const current = await readFile(OUT, "utf8").catch((e) => {
    if (e.code !== "ENOENT") throw e;
    return "";
  });
  if (current !== next) {
    console.error(
      `${OUT} does not match what this script generates now.\n` +
        `  @abaplint/runtime@${version}, esbuild@${esbuildVersion}\n` +
        "The usual cause is a runtime bump without a rebuild, but an esbuild\n" +
        "bump or an edit to this script produces the same mismatch.\n" +
        "Run: node scripts/build-runtime-bundle.mjs",
    );
    process.exit(1);
  }
  console.log(
    `${OUT} is up to date (@abaplint/runtime@${version}, esbuild@${esbuildVersion})`,
  );
} else {
  await writeFile(OUT, next);
  console.log(`Wrote ${OUT} from @abaplint/runtime@${version} (${next.length} bytes)`);
}
